//! NIST ACVP known-answer vectors for ML-DSA-65 (FIPS 204), test only.
//!
//! Source: usnistgov/ACVP-Server at commit
//! 2972def23bf9f3680c2c531561ed9bdd0f1086ad,
//! `gen-val/json-files/ML-DSA-sigVer-FIPS204/internalProjection.json`
//! (tgId 3: external interface, pure, ML-DSA-65) and
//! `ML-DSA-keyGen-FIPS204/internalProjection.json` (tgId 2, tcId 26).
//! Values are copied verbatim as hex; nothing here is derived.

/// One sigVer case: verify(pk, message, context, signature) == expected.
pub(crate) struct SigVer {
    pub tc_id: u32,
    pub expected: bool,
    pub reason: &'static str,
    pub pk: &'static str,
    pub message: &'static str,
    pub context: &'static str,
    pub signature: &'static str,
}

